import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);int s1=sc.nextInt(),s2=sc.nextInt(),s3=sc.nextInt();int[]A=new int[s1],B=new int[s2],C=new int[s3];for(int i=0;i<s1;i++)A[i]=sc.nextInt();for(int i=0;i<s2;i++)B[i]=sc.nextInt();for(int i=0;i<s3;i++)C[i]=sc.nextInt();int i=0,j=0,k=0;StringBuilder sb=new StringBuilder();while(i<s1&&j<s2&&k<s3){if(A[i]==B[j]&&B[j]==C[k]){sb.append(A[i]).append(' ');i++;j++;k++;}else if(A[i]<=B[j]&&A[i]<=C[k])i++;else if(B[j]<=A[i]&&B[j]<=C[k])j++;else k++;}System.out.println(sb.toString().trim());}}
